-- Hranice okresů ČR pro doplnění listings.district z GPS (fill_missing_districts ve scraperu).
-- Data: © přispěvatelé OpenStreetMap (ODbL), relace boundary=administrative admin_level=5,
-- staženo 6. 10. 2026 přes Nominatim (polygon_threshold=0.0005 ≈ 50 m). Praha v datech není (není okres).
-- Použití: make db < scripts/migrate_districts.sql   (idempotentní – tabulku naplní znovu)

CREATE TABLE IF NOT EXISTS re_realestate.districts (
    code   text PRIMARY KEY,                       -- LAU 1, např. CZ0647
    name   text NOT NULL,                          -- "Znojmo", "Brno-venkov" – stejný tvar jako listings.district
    osm_id bigint,
    geom   geometry(Polygon, 4326) NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_districts_geom ON re_realestate.districts USING gist (geom);

BEGIN;
DELETE FROM re_realestate.districts;
COMMIT;

\echo 'Okresy nahrány:'
SELECT count(*) FROM re_realestate.districts;
